local _, WFJ = ...
WFJ.Data.add("quest", {
  [97243] = { "Il richiamo del fuoco", "Porta la Torch of Dormant Flame a Olariaan Swiftburn allo Shrine of Flames, nei Gustberry Lowlands.", "Anche se siamo nel regno di Skywall, questo resta il piano elementale. Gli spiriti di tutti e quattro gli elementi ci parlano, se ci degniamo di ascoltare. Uno di noi Windshaper è in particolare sintonia con l'elemento del fuoco: uno shen'dorei di nome Olariaan Swiftburn.\n\nPortagli questo allo Shrine of Flames, nei Gustberry Lowlands. Lo troverai nascosto lungo il bordo dell'isola, a ovest di Valanaar.", "Sì, {name}? Che cos'hai lì?", "Dunque hai portato la torcia. Sì, giovane {class}, posso insegnarti a rispondere al richiamo del fuoco. Non sarà facile, ma niente di ciò che facciamo in questo regno è mai facile.", 0x53f3b76b, 0x10e8fa30, 0xb32aea3b, 0xacd1e0ef, 0x89691ed7, "....." },
  [97244] = { "Il richiamo del fuoco", "Uccidi Skypriest Faladiel nei Gustberry Lowlands e raccogli il Faladiel's Heart.", "C'è uno Skypriest degli Al'Aketh di nome Faladiel. Un tempo era un invocatore della fiamma e un fedele Windshaper. Come tanti Al'Aketh, ha barattato la sua lealtà con il potere, e ora le sue mani sono macchiate del sangue dei suoi ex fratelli e sorelle.\n\nTroverai lo Skypriest Faladiel alla fattoria a nord-est, oltre Valanaar, appena a sud dello Shrine of Akir. Uccidi il traditore. Portami il suo cuore. È un compito macabro, ma serve per il rituale che dobbiamo compiere.", "Il cuore di un traditore è un reagente potente. Le fiamme accetteranno avidamente un'offerta simile e arderanno più intense mentre lo consumano.", "I Windshaper non dimenticano, e il sangue si paga sempre con il sangue. Mi compiace che tu sia riuscit<o/a> a consegnare a quel traditore quest'ultimo, doloroso promemoria del nostro credo.\n\nTuttavia, questo cuore non sarà l'unica cosa ad alimentare le fiamme oggi. C'è un altro compito da svolgere.", 0x53f3b76b, 0x7c8f63a5, 0x8ff65707, 0x6c645a00, 0x1c368781, "....." },
  [97245] = { "Il richiamo del fuoco", "Trova la dimora di Kuramaa negli Shen'dar Highlands e sconfiggi lo spirito in combattimento. Quando avrai vinto, porta la Kuramaa's Mask a Olariaan Swiftburn nei Gustberry Lowlands.", "Gli abitanti degli Shen'dar Highlands parlano di un antico spirito della foresta chiamato Kuramaa. Dicono che viva dentro un ceppo contorto in cima a una collina, vicino all'Anchor Pylon degli altipiani.\n\nVa' sugli altipiani e trova quel ceppo. Batti il pugno sulla corteccia e Kuramaa apparirà. Sconfiggi lo spirito in combattimento e portami la sua maschera di legno.\n\nMa sta' attent<o/a>: questa entità sarà straordinariamente resistente a gran parte della tua magia. Solo il tocco della fiamma potrà abbattere lo spirito.", "Lo spirito di Kuramaa è eterno, e si manifesterà di nuovo quando ce ne sarà bisogno. La sua maschera è una fonte di grande potere e si rivelerà preziosissima per il rituale che dobbiamo compiere.", "Ora abbiamo ciò che ci serve. Accenderemo la fiamma eterna e comunicheremo con gli spiriti del fuoco.", 0x53f3b76b, 0xf10b3312, 0x5b054c6d, 0xf9b94402, 0xe1d99925, "....." },
  [97257] = { "Il richiamo del fuoco", "Aspetta che Olariaan inizi il rituale al Brazier of Offering e segui le sue istruzioni.\n\nDevi portare la Fiamma Eterna a Valanaar prima che scada il tempo.", "Ora eseguiremo il rituale.\n\nMetterò i materiali sull'altare e richiamerò gli spiriti della fiamma. Se l'offerta sarà accettata, appariranno e accenderanno la Fiamma Eterna. Allora tu terrai avanti la torcia e catturerai la fiamma.\n\nPorta la torcia accesa a Valanaar e mettila nel Brazier of Eternal Flames. Devi farlo in fretta, perché le fiamme dei Firelands si dissipano rapidamente qui a Skywall.", "Hai fatto bene ad arrivare fin qui. Fai onore ai Windshaper, {name}.", "È fatta. La Fiamma Eterna arde di nuovo.\n\nLa tua prova è completa. Sono lieto di consegnarti il tuo Totem del Fuoco. Usa bene questo simbolo di potere nei tuoi viaggi, {name}.\n\nRicorda solo che il potere del piano elementale serve chi lo rispetta e consuma chi non lo fa. Questa è la nostra via.", 0x53f3b76b, 0x0208cd7e, 0x4a530335, 0x6aa6ef08, 0xaed39338, "....." },
  [97899] = { "Campeggio 101: Alchimia", nil, "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
  [97900] = { "Campeggio 101: Forgiatura", nil, "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una Sharpening Wheel. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, nil, 0x469a706e, nil, nil, ".m.mm" },
  [97901] = { "Campeggio 101: Incantamento", nil, "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Enchanted Lute per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [97902] = { "Campeggio 101: Ingegneria", nil, "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, nil, 0x549b28c0, nil, nil, ".m.mm" },
  [97903] = { "Campeggio 101: ⟦First Aid=Primo Soccorso⟧", nil, "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un First Aid Kit per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un First Aid Kit tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, nil, 0x32ff3188, nil, 0x3a282524, ".m.m." },
  [97904] = { "Campeggio 101: Pesca", nil, "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, nil, 0xe0c1c700, nil, 0x1bcf05fd, nil, nil, ".m.mm" },
  [97905] = { "Campeggio 101: Erbalismo", nil, "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un'Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e un'Incense Candle può dare una spinta che chi usa la magia apprezzerà di certo.", nil, nil, 0xd7cde71c, nil, 0xe0048777, nil, nil, ".m.mm" },
  [97906] = { "Campeggio 101: Conciatura", nil, "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [97907] = { "Campeggio 101: Estrazione", nil, "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, nil, 0x8ef0fff6, nil, nil, ".m.mm" },
  [97908] = { "Campeggio 101: Scuoiatura", nil, "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Camp Chair per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una Camp Chair tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, nil, 0x1755b1ba, nil, 0x98c24a76, ".m.m." },
  [97915] = { "Campeggio 101: Alchimia", nil, "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
